type WaterHelpThreadEvent = {
  id: string;
  requestId: string;
  faultId: string;
  actionType: WaterHelpThreadAction;
  createdAt: string;
  priority: string;
  status: string;
  newStatus: string;
  message: string;
  actor: {
    userId: string;
    name: string;
    role: string;
    deviceId: string;
    deviceTokenHash: string;
  };
  target: {
    userId: string;
    name: string;
    role: string;
    department: string;
  };
  mapContext: {
    areaLabel: string;
    roadLabel: string;
    zoneLabel: string;
    mapPath: string;
    canOpenMap: boolean;
  };
  delivery: {
    pantavionThreadRecorded: true;
    smsRequested: boolean;
    smsStatus: "not_requested" | "not_sent_provider_not_connected";
    smsPhoneMasked: string;
  };
  audit: {
    storedPrivate: true;
    visibleToFounderAdmin: true;
    requiresIdentitySessionForFullRead: true;
    note: string;
  };
};

