async function stopSharing(){ if(!backendReady)return;setBusy(true);setNotice("");const {error}=await supabase.from("social_location_shares").upsert({user_id:userId,enabled:false,audience:"nobody",updated_at:new Date().toISOString()});setBusy(false);if(error)return setNotice(error.message);setEnabled(false);setNotice("Η κοινοποίηση θέσης σταμάτησε."); }
  function navigateTo(item:VisibleLocation){window.open(`https://www.google.com/maps/dir/?api=1&destination=${encodeURIComponent(`${item.latitude},${item.longitude}`)}`,"_blank","noopener,noreferrer");}
  function findNearby(query:string){if(!myPoint)return setNotice("Ενεργοποίησε πρώτα την τοποθεσία σου για να βρούμε τι υπάρχει κοντά σου.");window.open(`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(query)}&center=${myPoint.latitude},${myPoint.longitude}`,"_blank","noopener,noreferrer");}

